<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, user-scalable=no, viewport-fit=cover" />
<title>HYPERLANE — endless neon lane runner</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Chakra+Petch:wght@400;500;600;700&family=Space+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
:root{
  --ink:#03040c; --ink2:#080c18;
  --cyan:#25f2ff; --mag:#ff2b7f; --amber:#ffbd3a; --violet:#8b5cff;
  --txt:#e7ecff; --mut:#8b95c8;
  --panel:rgba(5,8,18,.74); --brd:rgba(37,242,255,.32);
}
*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}
html,body{height:100%;margin:0;background:var(--ink);overflow:hidden;overscroll-behavior:none}
body{font-family:'Space Grotesk',ui-sans-serif,system-ui,sans-serif;color:var(--txt);letter-spacing:.015em}
#scene{position:fixed;inset:0;display:block;touch-action:none}
.disp{font-family:'Chakra Petch','Space Grotesk',sans-serif;font-weight:700;text-transform:uppercase}

/* ---------- post fx layers ---------- */
#fx-scan{position:fixed;inset:0;pointer-events:none;z-index:55;opacity:.42;
  background:repeating-linear-gradient(to bottom,rgba(0,0,0,.30) 0 1px,rgba(0,0,0,0) 1px 3px)}
#fx-vig{position:fixed;inset:0;pointer-events:none;z-index:56;
  background:radial-gradient(ellipse at 50% 58%,rgba(0,0,0,0) 38%,rgba(1,2,8,.78) 100%)}
#fx-edge{position:fixed;inset:0;pointer-events:none;z-index:57;opacity:.55;
  box-shadow:inset 0 0 90px rgba(37,242,255,.14),inset 0 0 26px rgba(255,43,127,.10)}
#flash{position:fixed;inset:0;pointer-events:none;z-index:60;background:#fff;opacity:0}
#flash.go{animation:flashAnim .62s cubic-bezier(.1,.7,.3,1) forwards}
@keyframes flashAnim{0%{opacity:.9}40%{opacity:.32}100%{opacity:0}}
#redflash{position:fixed;inset:0;pointer-events:none;z-index:59;opacity:0;
  background:radial-gradient(ellipse at 50% 60%,rgba(255,43,127,.0) 30%,rgba(255,43,127,.35) 100%)}
#redflash.go{animation:redAnim .9s ease-out forwards}
@keyframes redAnim{0%{opacity:1}100%{opacity:0}}

/* ---------- HUD ---------- */
#hud{position:fixed;inset:0;pointer-events:none;z-index:20}
.row-top{position:absolute;top:clamp(10px,1.8vw,24px);left:clamp(10px,1.8vw,24px);right:clamp(10px,1.8vw,24px);
  display:flex;align-items:flex-start;justify-content:space-between;gap:10px}
.panel{position:relative;background:var(--panel);border:1px solid var(--brd);
  padding:10px 15px 11px;
  clip-path:polygon(0 0,calc(100% - 13px) 0,100% 13px,100% 100%,13px 100%,0 calc(100% - 13px));
  box-shadow:inset 0 0 26px rgba(37,242,255,.09),0 8px 26px rgba(0,0,0,.55);
  transition:transform .3s ease, box-shadow .3s ease}
.panel .label{font-family:'Chakra Petch',sans-serif;font-size:9px;font-weight:600;letter-spacing:.28em;
